L = lambda path, label, small="": (path, label, small)

from cabs_data import oneway as _ow, inr as _inr, FLEET_BY_ID as _FB
_O = lambda vid, km, f: _inr(_ow(vid, km, f))           # one-way fare from the engine
_S = lambda km, f: _O("sedan", km, f)
_DAY = lambda vid, days=1: _inr(250 * days * _FB[vid]["hire"] + (days - 1) * _FB[vid]["night"])  # full-day hire, 250 km/day minimum

from cabs_data import r99 as _r99
_RT = lambda vid, km, days: _inr(_r99(max(2 * km, 250 * days) * _FB[vid]["hire"]) + (days - 1) * _FB[vid]["night"])  # round trip, same formula as the calculator
_TOUR = lambda vid, km, days: _inr(_r99(max(km, 250 * days) * _FB[vid]["hire"]) + (days - 1) * _FB[vid]["night"])  # 26 Oct 2026: multi-day circuit (km = total km driven), same formula as the calculator round trip

