# ------------------------------------------------------------------ PATHANKOT -> DALHOUSIE
dict(slug="pathankot-to-dalhousie-taxi", kind="route", route="pathankot-to-dalhousie-taxi",
 title="Pathankot to Dalhousie Taxi", seo_title="Pathankot to Dalhousie Taxi from " + _S(80, 1.1) + " | Station Pickup",
 seo_desc="Pathankot to Dalhousie taxi from " + _S(80, 1.1) + ", Innova Crysta from " + _O("crysta", 80, 1.1) + ". 80 km via Dunera & Banikhet, 2.5–3 hrs. Station & airport pickup, Khajjiar add-on.",
 focus="pathankot to dalhousie taxi",
 kicker="Pathankot → Dalhousie · Khajjiar",
 tag="Pathankot to Dalhousie by taxi, off the train and up the hills",
 sub="Pickup at Pathankot Junction, Chakki Bank (Pathankot Cantt), Pathankot airport or the bus stand, and a drop at your hotel on Gandhi Chowk, Subhash Chowk, Banikhet or the Khajjiar road — with a driver who knows the bends of NH154A.",
 answer="A Pathankot to Dalhousie taxi covers about <b>80 km in 2.5–3 hours</b> via Dunera and Banikhet on NH154A, climbing from about 330 m to roughly 1,970 m. One-way fares start around <b>" + _S(80, 1.1) + " for a sedan</b>, <b>" + _O("ertiga", 80, 1.1) + " for an Ertiga</b> and <b>" + _O("crysta", 80, 1.1) + " for an Innova Crysta</b>; tolls, parking and the Himachal entry fee are extra. Khajjiar is 24 km further.",
 facts=[("Distance","~80 km"),("Drive time","2.5–3 hrs"),("Route","NH154A via Dunera"),("Altitude","~330 m → ~1,970 m"),("Khajjiar","+24 km · ~1,920 m"),("Sedan from",_S(80, 1.1) + " one-way")],
 stops=[("Pathankot · Chakki Bank","Pickup at Pathankot Junction, Chakki Bank (Pathankot Cantt) station, Pathankot airport, the bus stand or any hotel in town. Overnight trains from Delhi arrive early, so the car is usually rolling by 7 am."),
        ("The Shivalik foothills","Out of Pathankot the road leaves the Punjab plains and starts to wind through low, forested Shivalik ridges — the first views of the Dhauladhar snow line show up on clear mornings."),
        ("Dunera","The last big stop on the Punjab side and the usual tea-and-parantha halt. Dunera is known for its stalls of mango papad (aam papad) — a good thing to buy for the road."),
        ("Into Himachal","After Dunera the highway crosses into Chamba district of Himachal, where cars registered outside Himachal pay the entry fee. The climb gets steeper and the pine forest thicker from here."),
        ("Banikhet","The junction town just below Dalhousie: NH154A carries on to Chamba, while the Dalhousie road turns up the hill. Banikhet has fuel, ATMs and several hotels of its own."),
        ("Dalhousie","Drop at your hotel near Gandhi Chowk, Subhash Chowk, the Mall or on the Khajjiar road. A few hotels sit on pedestrian lanes; the driver stops at the closest point a car can reach.")],
 map=dict(path=["Pathankot","Dunera","Banikhet","Dalhousie"], labels=["Pathankot","Dunera","Dalhousie"], ctx=["Khajjiar","Chamba","Nurpur"], via=["Dunera","Banikhet","NH154A"]),
 tips=[("Take the early train","Overnight trains from Delhi reach Pathankot or Chakki Bank between about 4 and 7 am. Share the train number — the driver tracks delays and waits at the exit with your name, so you are in Dalhousie by breakfast."),
       HP_ENTRY,
       ("Add Khajjiar the same day","Khajjiar's meadow is 24 km beyond Dalhousie past Kalatop forest. Ask for a Pathankot → Khajjiar → Dalhousie drop and we quote the extra distance upfront — easier than booking a second car the next morning."),
       ("Hairpins and motion sickness","The last 40 km from Dunera to Dalhousie is a steady climb with tight bends. Eat light, sit in front if you feel queasy, and tell the driver if you want a short stop — there is no rush."),
       ("Winter and monsoon","From December to February snow can fall in Dalhousie and the last stretch above Banikhet may need chains or a short wait. In July–August landslides sometimes block NH154A; we check the road the evening before and adjust the start time."),
       ("Going on to Dharamshala?","Pathankot → Dalhousie → Khajjiar → Dharamshala is a classic 3–4 day circuit in one car. Round trips and tours are billed per kilometre, so one cab for the whole loop usually costs less than separate one-way drops.")],
 faqs=[("What is the taxi fare from Pathankot to Dalhousie?","One-way fares start around " + _O("hatch", 80, 1.1) + " for a hatchback, " + _S(80, 1.1) + " for a sedan, " + _O("ertiga", 80, 1.1) + " for an Ertiga, " + _O("carens", 80, 1.1) + " for a Kia Carens and " + _O("crysta", 80, 1.1) + " for an Innova Crysta. A 12-seater Tempo Traveller starts around " + _O("tempo", 80, 1.1) + ". Tolls, parking and the Himachal entry fee are extra at actuals; peak dates cost more."),
       ("How far is Dalhousie from Pathankot by road?","About 80–85 km depending on your pickup point, via Dunera and Banikhet on NH154A. The drive takes 2.5 to 3 hours with a tea stop; Khajjiar is another 24 km past Dalhousie."),
       ("Can you pick us up at Pathankot or Chakki Bank railway station?","Yes. The driver waits outside Pathankot Junction or Chakki Bank (Pathankot Cantt) with your name, and also picks up from Pathankot airport, the bus stand or any hotel. Share the train or flight number and we track delays."),
       ("Can we go to Khajjiar in the same taxi?","Yes. Khajjiar is 24 km beyond Dalhousie. You can book a drop straight to Khajjiar, or a Pathankot → Khajjiar → Dalhousie trip with sightseeing on the way; we quote the extra kilometres before you confirm."),
       ("Is the Dalhousie to Pathankot taxi fare the same?","Yes. The same one-way fares apply from Dalhousie, Banikhet or Khajjiar to Pathankot Junction, Chakki Bank, Pathankot airport or the bus stand. For an evening train, leave Dalhousie by early afternoon to allow for hill traffic."),
       ("Do roads to Dalhousie close in winter?","The road usually stays open, but after fresh snow (December to February) the last stretch above Banikhet can be slippery for a day or two. Drivers carry chains and we confirm the conditions the day before your trip."),
       ("Do you do Pathankot–Dalhousie–Khajjiar round trips?","Yes. Round trips are billed per kilometre driven (sedan ₹12/km, 250 km daily minimum) plus ₹400 a night driver allowance. A 2-day Pathankot–Dalhousie–Khajjiar–Pathankot trip in a sedan starts around " + _RT("sedan", 80, 2) + "."),
       ("Can I book a Dalhousie–Dharamshala tour in the same cab?","Yes. A Pathankot → Dalhousie → Khajjiar → Dharamshala → Pathankot circuit fits in 3–4 days and is billed per kilometre with a 250 km daily minimum plus driver allowance. Tell us your dates and we send one all-in quote.")],
 related=[L("/cabs/pathankot-to-dharamshala-taxi/","Pathankot to Dharamshala taxi","Station & airport pickup"),L("/cabs/dharamshala-taxi-service/","Dharamshala taxi service","Local trips · Dalhousie drops"),L("/dalhousie/","Dalhousie guide"),L("/destination/dalhousie-tour-packages/","Dalhousie tour packages"),L("/tours/magnificent-dharamshala-dalhousie-tour-package-from-pathankot/","Dharamshala–Dalhousie from Pathankot","Hotel + cab"),L("/cabs/amritsar-taxi-service/","Amritsar taxi service","Drops to Dalhousie")],
 wa="Hi Suzu Travels, I need a Pathankot to Dalhousie taxi. Pickup (station/airport/address): ___ , train/flight: ___ , date: ___ , people: ___ , drop (Dalhousie hotel/Khajjiar): ___"),

